const sourceText=new WeakMap(),sourceAttributes=new WeakMap();
window.siteLanguage=/^\/en(?:\/|$)/.test(location.pathname)?'en':'pt';
function english(text){if(EN[text])return EN[text];const prefix=text.match(/^(\d+ \/ )(.*)$/);if(prefix)return prefix[1]+english(prefix[2]);for(const sep of [' / ',' — '])if(text.includes(sep))return text.split(sep).map(english).join(sep);return text;}
window.siteTranslate=function(value){const text=String(value??'');return window.siteLanguage==='en'?english(text):text;};
window.applySiteLanguage=function(){
 const en=window.siteLanguage==='en';document.documentElement.lang=en?'en':'pt-MZ';
 const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let node;
 while(node=walker.nextNode()){
  if(node.parentElement?.closest('script,style,.language-switch,#feedback,#contact-challenge'))continue;
  const original=sourceText.get(node)??node.nodeValue;sourceText.set(node,original);
  const text=original.trim();const translated=en?english(text):text;
  const value=original.replace(text,translated);if(node.nodeValue!==value)node.nodeValue=value;
 }
 document.querySelectorAll('[alt],[aria-label],[placeholder]').forEach(el=>{
  if(el.closest('.language-switch,#contact-challenge,.banner-toggle'))return;
  let attrs=sourceAttributes.get(el);if(!attrs){attrs={};for(const key of ['alt','aria-label','placeholder'])if(el.hasAttribute(key))attrs[key]=el.getAttribute(key);sourceAttributes.set(el,attrs);}
  for(const [key,value]of Object.entries(attrs))el.setAttribute(key,en?english(value):value);
 });
 const title=window.currentSEO?.title||'Inbytes — Tecnologia com propósito';document.title=en?english(title):title;
 const meta=document.querySelector('meta[name="description"]');if(meta){const pt=window.currentSEO?.description||'Inbytes — websites, sistemas e soluções digitais em Moçambique';meta.content=en?english(pt):pt;}
 const bannerToggle=document.querySelector('.banner-toggle');if(bannerToggle){const label=window.siteTranslate(bannerToggle.dataset.paused==='true'?'Retomar banner':'Pausar banner');bannerToggle.setAttribute('aria-label',label);bannerToggle.setAttribute('title',label);}
 const status=document.querySelector('#feedback');if(status){const text=status.textContent.trim();if(en)status.textContent=english(text);else{const pt=Object.keys(EN).find(key=>EN[key]===text);if(pt)status.textContent=pt;}}
 document.querySelectorAll('[data-language]').forEach(button=>{button.setAttribute('aria-pressed',String(button.dataset.language===window.siteLanguage));button.onclick=()=>{const base=location.pathname.replace(/^\/en(?=\/|$)/,'')||'/';const target=(button.dataset.language==='en'?'/en':'')+base+location.search+location.hash;if(location.pathname!==target.split('?')[0].split('#')[0])location.assign(target);};});
};
